const gd: libGDevelop = global.gd;

/**
 * Recursively collects the paths of all events sharing the given aiGeneratedEventId.
 * A whole generation batch shares one id, so an id can match several events.
 */
const findAllEventPathsByAiGeneratedEventId = (
  eventsList: gdEventsList,
  targetId: string,
  currentPath: EventPath = [],
  foundPaths: Array<EventPath> = []
): Array<EventPath> => {
  for (let i = 0; i < eventsList.getEventsCount(); i++) {
    const event = eventsList.getEventAt(i);
    const eventPath = [...currentPath, i];

    if (event.getAiGeneratedEventId() === targetId) {
      foundPaths.push(eventPath);
    }

    if (event.canHaveSubEvents()) {
      findAllEventPathsByAiGeneratedEventId(
        event.getSubEvents(),
        targetId,
        eventPath,
        foundPaths
      );
    }
  }
  return foundPaths;
};

/**
 * Parses an event path string (e.g., "event-0.1.2") into an array of 0-based indices (e.g., [0, 1, 2]).
 * Throws an error for invalid formats or non-positive indices.
 */
const parseEventPath = (pathString: string): EventPath => {
  const originalPathString = pathString;
  if (!pathString.startsWith('event-')) {
    // Fallback for paths that might not have the "event-" prefix, like "1.2.3"
    // This is a lenient parsing, primary expectation is "event-" prefix.
    const partsNoPrefix = pathString.split('.');
    if (
      partsNoPrefix.length > 0 &&
      partsNoPrefix.every(s => s !== '' && Number.isInteger(Number(s)))
    ) {
      console.warn(
        `Event path string "${originalPathString}" does not start with "event-". Parsed as direct indices.`
      );
    } else {
      throw new Error(
        `Invalid event path string format: "${originalPathString}". Expected "event-X.Y.Z" or "X.Y.Z".`
      );
    }
  } else {
    pathString = pathString.substring('event-'.length);
  }

  const parts = pathString.split('.');
  if (
    parts.length === 0 ||
    parts.some(s => s === '' || !Number.isInteger(Number(s)))
  ) {
    throw new Error(
      `Invalid event path string content: "${originalPathString}". Ensure numbers are separated by dots.`
    );
  }
  return parts.map(s => {
    const num = Number(s);
    if (num < 0) {
      throw new Error(
        `Event path indices must be positive in string "${originalPathString}", but found ${num}.`
      );
    }
    return num;
  });
};

/**
 * Navigates an event tree to find the parent EventsList and the 0-based index
 * for an event targeted by the given path.
 */
const getParentListAndIndex = (
  rootEventsList: gdEventsList,
  path: EventPath,
  operationTypeForErrorMessage: 'access' | 'insertion'
): { parentList: gdEventsList, eventIndexInParentList: number } => {
  if (path.length === 0) {
    throw new Error('Path cannot be empty for getParentListAndIndex.');
  }

  let currentList = rootEventsList;
  const pathForErrorMessage = path.join('.');

  for (let i = 0; i < path.length - 1; i++) {
    const eventIndex = path[i];
    if (eventIndex < 0 || eventIndex >= currentList.getEventsCount()) {
      throw new Error(
        `Invalid event path: index ${eventIndex} out of bounds at depth ${i +
          1} (max: ${currentList.getEventsCount() -
          1}). Path: ${pathForErrorMessage}`
      );
    }
    const event = currentList.getEventAt(eventIndex);
    if (!event.canHaveSubEvents()) {
      throw new Error(
        `Event at path segment ${i +
          1} (index ${eventIndex}) cannot have sub-events. Path: ${pathForErrorMessage}`
      );
    }
    currentList = event.getSubEvents();
  }

  const finalIndex = path[path.length - 1];
  if (finalIndex < 0) {
    throw new Error(
      `Invalid event path: final index ${finalIndex} is negative. Path: ${pathForErrorMessage}.`
    );
  }

  // For insertion, index can be equal to count (to append). For access, it must be less than count.
  if (
    operationTypeForErrorMessage === 'insertion' &&
    finalIndex > currentList.getEventsCount()
  ) {
    throw new Error(
      `Invalid event path for insertion: final index ${finalIndex} is out of bounds. Max allowed for insertion: ${currentList.getEventsCount()}. Path: ${pathForErrorMessage}`
    );
  } else if (
    operationTypeForErrorMessage === 'access' &&
    finalIndex >= currentList.getEventsCount()
  ) {
    throw new Error(
      `Invalid event path for access: final index ${finalIndex} is out of bounds. Max allowed for access: ${currentList.getEventsCount() -
        1}. Path: ${pathForErrorMessage}`
    );
  }

  return { parentList: currentList, eventIndexInParentList: finalIndex };
};

/**
 * Retrieves an event at a specific path from a root EventsList.
 */
const getEventByPath = (
  rootEventsList: gdEventsList,
  path: EventPath
): gdBaseEvent => {
  const { parentList, eventIndexInParentList } = getParentListAndIndex(
    rootEventsList,
    path,
    'access'
  );
  // Bounds check already done by getParentListAndIndex for 'access'
  return parentList.getEventAt(eventIndexInParentList);
};

const JS_CODE_EVENT_TYPE = 'BuiltinCommonInstructions::JsCode';

/**
 * The settings of a JavaScript code event that the events generation never
 * describes: it always serializes the default ones. When such an event replaces
 * an existing one, they are kept from the replaced event.
 */
const JS_CODE_EVENT_SETTINGS_KEPT_WHEN_REPLACED = [
  'useStrict',
  'eventsSheetExpanded',
];

/**
 * True for the operations replacing an existing event by the generated one.
 */
const isEventReplacedByGeneratedEvents = (operationName: string): boolean =>
  operationName === 'insert_and_replace_event' ||
  operationName === 'replace_entire_event_and_sub_events' ||
  operationName === 'replace_event_but_keep_existing_sub_events';

/**
 * When a generated JavaScript code event replaces an existing one, keep the
 * settings of the replaced event that the generation can't describe. This is done
 * on the serialized generated events, as these settings have no setter in the editor.
 */
const keepReplacedJsCodeEventSettings = ({
  rootEventsList,
  replacedEventPath,
  generatedEventsContent,
}: {|
  rootEventsList: gdEventsList,
  replacedEventPath: EventPath,
  generatedEventsContent: Array<Object>,
|}): void => {
  const generatedEvent = generatedEventsContent[0];
  if (!generatedEvent || generatedEvent.type !== JS_CODE_EVENT_TYPE) return;

  let replacedEvent = null;
  try {
    replacedEvent = getEventByPath(rootEventsList, replacedEventPath);
  } catch (error) {
    // An invalid path is reported when the operation is applied.
    return;
  }
  if (replacedEvent.getType() !== JS_CODE_EVENT_TYPE) return;

  const serializedReplacedEvent = serializeToJSObject(replacedEvent);
  JS_CODE_EVENT_SETTINGS_KEPT_WHEN_REPLACED.forEach(settingName => {
    generatedEvent[settingName] = serializedReplacedEvent[settingName];
  });
};

type EventOperationType =
  | 'delete'
  | 'insert'
  | 'insertAsSub'
  | 'replaceKeepSubEvents'
  | 'insertActionsConditionsAtEnd'
  | 'insertActionsConditionsAtStart'
  | 'replaceAllActions'
  | 'replaceAllConditions';
type EventInsertKind = 'replacement' | 'before' | 'after';
type EventOperation = {|
  type: EventOperationType,
  path: EventPath,
  eventsToInsert?: gdEventsList,
  // For 'insert' operations, how the insertion point was defined relatively
  // to the existing events (used to disambiguate insertions sharing a path).
  insertKind?: EventInsertKind,
  // Position of the change in the input, to keep the order of the changes
  // when several of them target the same insertion point.
  order?: number,
|};

/**
 * Copy instructions from source list to target list at the specified position.
 */
const copyInstructions = (
  source: gdInstructionsList,
  target: gdInstructionsList,
  position: number
): void => {
  target.insertInstructions(source, 0, source.size(), position);
};

/**
 * Helper to get conditions from an event if it supports them.
 */
const getEventConditions = (event: gdBaseEvent): gdInstructionsList | null => {
  const eventType = event.getType();
  if (eventType === 'BuiltinCommonInstructions::Standard') {
    return gd.asStandardEvent(event).getConditions();
  } else if (eventType === 'BuiltinCommonInstructions::While') {
    return gd.asWhileEvent(event).getConditions();
  } else if (eventType === 'BuiltinCommonInstructions::Repeat') {
    return gd.asRepeatEvent(event).getConditions();
  } else if (eventType === 'BuiltinCommonInstructions::ForEach') {
    return gd.asForEachEvent(event).getConditions();
  } else if (eventType === 'BuiltinCommonInstructions::ForEachChildVariable') {
    return gd.asForEachChildVariableEvent(event).getConditions();
  }
  return null;
};

/**
 * Helper to get actions from an event if it supports them.
 */
const getEventActions = (event: gdBaseEvent): gdInstructionsList | null => {
  const eventType = event.getType();
  if (eventType === 'BuiltinCommonInstructions::Standard') {
    return gd.asStandardEvent(event).getActions();
  } else if (eventType === 'BuiltinCommonInstructions::While') {
    return gd.asWhileEvent(event).getActions();
  } else if (eventType === 'BuiltinCommonInstructions::Repeat') {
    return gd.asRepeatEvent(event).getActions();
  } else if (eventType === 'BuiltinCommonInstructions::ForEach') {
    return gd.asForEachEvent(event).getActions();
  } else if (eventType === 'BuiltinCommonInstructions::ForEachChildVariable') {
    return gd.asForEachChildVariableEvent(event).getActions();
  }
  return null;
};

/**
 * Helper to get while conditions from a While event.
 */
const getEventWhileConditions = (
  event: gdBaseEvent
): gdInstructionsList | null => {
  if (event.getType() === 'BuiltinCommonInstructions::While') {
    return gd.asWhileEvent(event).getWhileConditions();
  }
  return null;
};

/**
 * When several operations have the same path, the path means different things:
 * for an insertion, it's an insertion point (a "gap"), while for the other
 * operations it designates the existing event at this index. Operations on the
 * existing event must then run first, otherwise the inserted events would take
 * its place and be wrongly edited or deleted. Deletions still run just before
 * insertions, so that the delete+insert pair generated for
 * "insert_and_replace_event" stays in order.
 */
const getOperationPriorityForSamePath = (type: EventOperationType): number => {
  if (type === 'insert') return 2;
  if (type === 'delete') return 1;
  return 0;
};

/**
 * At the same insertion point, the events inserted first end up after those
 * inserted later. Insertions are then applied so that events end up in this
 * order: events inserted after the previous sibling, then events inserted
 * before the next sibling, then the replacement of the next sibling.
 */
const getInsertKindPriorityForSamePath = (
  insertKind?: EventInsertKind
): number => {
  if (insertKind === 'replacement') return 0;
  if (insertKind === 'before') return 1;
  return 2;
};

const comparePathsReverseLexicographically = (
  p1: EventPath,
  p2: EventPath
): number => {
  const maxLength = Math.max(p1.length, p2.length);
  for (let i = 0; i < maxLength; i++) {
    const val1 = i < p1.length ? p1[i] : -1;
    const val2 = i < p2.length ? p2[i] : -1;
    if (val1 > val2) return -1;
    if (val1 < val2) return 1;
  }
  return 0;
};

export const applyEventsChanges = (
  project: gdProject,
  sceneEvents: gdEventsList,
  eventOperationsInput: Array<AiGeneratedEventChange>,
  aiGeneratedEventId: string
): {| applied: number, errors: Array<string> |} => {
  const operations: Array<EventOperation> = [];
  const errors: Array<string> = [];

  eventOperationsInput.forEach(change => {
    const { operationName, operationTargetEvent, generatedEvents } = change;
    let parsedPath: EventPath | null = null;
    let localEventsToInsert: gdEventsList | null = null;

    try {
      // Check for comma-separated targets
      if (operationTargetEvent && operationTargetEvent.includes(',')) {
        if (operationName !== 'delete_event') {
          errors.push(
            `Operation "${operationName}" does not support multiple comma separated events as target.`
          );
          return;
        }

        // Handle comma-separated delete targets
        const targets = operationTargetEvent
          .split(',')
          .map(t => t.trim())
          .filter(t => t.length > 0);
        for (const target of targets) {
          let targetPath = null;
          const matchingPaths = findAllEventPathsByAiGeneratedEventId(
            sceneEvents,
            target
          );
          if (matchingPaths.length === 1) {
            targetPath = matchingPaths[0];
          } else if (matchingPaths.length > 1) {
            // A whole generation batch shares one aiGeneratedEventId, so it can
            // match several events. Refuse to guess instead of deleting the wrong one.
            errors.push(
              `aiGeneratedEventId "${target}" matches ${
                matchingPaths.length
              } events. Target a single event by its path (e.g. "event-7") instead. Skipping deletion of "${target}".`
            );
            continue;
          } else {
            try {
              targetPath = parseEventPath(target);
            } catch (pathParseError) {
              errors.push(
                `Could not find event with aiGeneratedEventId "${target}" and could not parse as path. Skipping deletion of "${target}".`
              );
              continue;
            }
          }
          operations.push({ type: 'delete', path: targetPath });
        }
        return;
      }

      if (operationTargetEvent) {
        // First search for events with the exact aiGeneratedEventId.
        const matchingPaths = findAllEventPathsByAiGeneratedEventId(
          sceneEvents,
          operationTargetEvent
        );

        if (matchingPaths.length === 1) {
          parsedPath = matchingPaths[0];
        } else if (matchingPaths.length > 1) {
          // A whole generation batch shares one aiGeneratedEventId, so it can
          // match several events. Refuse to guess instead of editing the wrong one.
          errors.push(
            `aiGeneratedEventId "${operationTargetEvent}" matches ${
              matchingPaths.length
            } events. Target a single event by its path (e.g. "event-7") instead. Skipping operation "${operationName}".`
          );
          return;
        } else {
          // Then try to parse as a path string (e.g., "event-0.1.2" or "0.1.2")
          try {
            parsedPath = parseEventPath(operationTargetEvent);
          } catch (pathParseError) {
            errors.push(
              `Could not find event with aiGeneratedEventId "${operationTargetEvent}" and could not parse as path. Skipping operation "${operationName}".`
            );
            return;
          }
        }
      } else if (operationName !== 'insert_at_end') {
        // Path is generally required, except for 'insert_at_end'.
        errors.push(
          `Skipping operation "${operationName}" due to missing operationTargetEvent path.`
        );
        return;
      }

      if (generatedEvents && operationName !== 'delete_event') {
        const eventsListContent = JSON.parse(generatedEvents);
        if (parsedPath && isEventReplacedByGeneratedEvents(operationName)) {
          keepReplacedJsCodeEventSettings({
            rootEventsList: sceneEvents,
            replacedEventPath: parsedPath,
            generatedEventsContent: eventsListContent,
          });
        }
        localEventsToInsert = new gd.EventsList();
        unserializeFromJSObject(
          localEventsToInsert,
          eventsListContent,
          'unserializeFrom',
          project
        );
        if (localEventsToInsert.isEmpty()) {
          errors.push(
            `Generated events for operation "${operationName}" (path: ${operationTargetEvent ||
              'N/A'}) are empty. Insertion might not add any events.`
          );
        }
        mapFor(0, localEventsToInsert.getEventsCount(), i => {
          if (!localEventsToInsert) return;

          const event = localEventsToInsert.getEventAt(i);
          event.setAiGeneratedEventId(aiGeneratedEventId);
        });
      }

      switch (operationName) {
        case 'insert_and_replace_event':
        case 'replace_entire_event_and_sub_events':
          if (!parsedPath) {
            errors.push(
              `Skipping "${operationName}" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({ type: 'delete', path: parsedPath });
          operations.push({
            type: 'insert',
            path: parsedPath,
            eventsToInsert: localEventsToInsert || undefined,
            insertKind: 'replacement',
          });
          // localEventsToInsert is now "owned" by the 'insert' operation,
          // it should not be deleted here in the switch case.
          break;
        case 'replace_event_but_keep_existing_sub_events':
          if (!parsedPath) {
            errors.push(
              `Skipping "replace_event_but_keep_existing_sub_events" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({
            type: 'replaceKeepSubEvents',
            path: parsedPath,
            eventsToInsert: localEventsToInsert || undefined,
          });
          break;
        case 'insert_before_event':
          if (!parsedPath) {
            errors.push(
              `Skipping "insert_before_event" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({
            type: 'insert',
            path: parsedPath,
            eventsToInsert: localEventsToInsert || undefined,
            insertKind: 'before',
          });
          break;
        case 'insert_after_event':
          if (!parsedPath) {
            errors.push(
              `Skipping "insert_after_event" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          // Insert after means we insert at path[last] + 1
          const insertAfterPath = [...parsedPath];
          insertAfterPath[insertAfterPath.length - 1] += 1;
          operations.push({
            type: 'insert',
            path: insertAfterPath,
            eventsToInsert: localEventsToInsert || undefined,
            insertKind: 'after',
          });
          break;
        case 'insert_as_sub_event':
          if (!parsedPath) {
            errors.push(
              `Skipping "insert_as_sub_event" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({
            type: 'insertAsSub',
            path: parsedPath, // This path is to the parent event
            eventsToInsert: localEventsToInsert || undefined,
          });
          break;
        case 'insert_actions_conditions_at_end':
          if (!parsedPath) {
            errors.push(
              `Skipping "insert_actions_conditions_at_end" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({
            type: 'insertActionsConditionsAtEnd',
            path: parsedPath,
            eventsToInsert: localEventsToInsert || undefined,
          });
          break;
        case 'insert_actions_conditions_at_start':
          if (!parsedPath) {
            errors.push(
              `Skipping "insert_actions_conditions_at_start" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({
            type: 'insertActionsConditionsAtStart',
            path: parsedPath,
            eventsToInsert: localEventsToInsert || undefined,
          });
          break;
        case 'replace_all_actions':
          if (!parsedPath) {
            errors.push(
              `Skipping "replace_all_actions" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({
            type: 'replaceAllActions',
            path: parsedPath,
            eventsToInsert: localEventsToInsert || undefined,
          });
          break;
        case 'replace_all_conditions':
          if (!parsedPath) {
            errors.push(
              `Skipping "replace_all_conditions" due to missing or invalid path.`
            );
            if (localEventsToInsert) localEventsToInsert.delete();
            return;
          }
          operations.push({
            type: 'replaceAllConditions',
            path: parsedPath,
            eventsToInsert: localEventsToInsert || undefined,
          });
          break;
        case 'delete_event':
          if (!parsedPath) {
            errors.push(
              `Skipping "delete_event" due to missing or invalid path.`
            );
            // No localEventsToInsert expected or created for delete_event.
            return;
          }
          // Ensure no events were accidentally parsed for delete.
          if (localEventsToInsert) {
            console.warn(
              'Internal warning: localEventsToInsert was populated for a "delete_event". Cleaning up.'
            );
            localEventsToInsert.delete();
          }
          operations.push({ type: 'delete', path: parsedPath });
          break;
        case 'insert_at_end':
          // Path for insert_at_end is synthetic, representing the end of the root list.
          operations.push({
            type: 'insert',
            path: [sceneEvents.getEventsCount()],
            eventsToInsert: localEventsToInsert || undefined,
            insertKind: 'after',
          });
          break;
        default:
          errors.push(
            `Unknown operationName: "${operationName}". Skipping operation.`
          );
          // Clean up localEventsToInsert if it was created for an unknown operation
          if (localEventsToInsert) localEventsToInsert.delete();
      }
    } catch (e) {
      errors.push(
        `Error processing event change (operation: "${operationName}", path: "${operationTargetEvent ||
          'N/A'}"): ${e.message}. Skipping this change.`
      );
      // Ensure cleanup if parsing/unserialization failed mid-way
      if (localEventsToInsert) {
        localEventsToInsert.delete();
      }
    }
  });

  // The same event can be targeted for deletion by several changes (for
  // example, a duplicated target in a comma separated list, or two
  // "insert_and_replace_event" on the same event). Only keep the first
  // deletion for a given path: applying it twice would delete the event
  // that took the place of the deleted one.
  const seenDeletionPaths = new Set<string>();
  const deduplicatedOperations = operations.filter(op => {
    if (op.type !== 'delete') return true;
    const pathKey = op.path.join('.');
    if (seenDeletionPaths.has(pathKey)) return false;
    seenDeletionPaths.add(pathKey);
    return true;
  });

  deduplicatedOperations.forEach((op, index) => {
    op.order = index;
  });

  deduplicatedOperations.sort((opA, opB) => {
    const pathComparison = comparePathsReverseLexicographically(
      opA.path,
      opB.path
    );
    if (pathComparison !== 0) return pathComparison;

    const priorityDifference =
      getOperationPriorityForSamePath(opA.type) -
      getOperationPriorityForSamePath(opB.type);
    if (priorityDifference !== 0) return priorityDifference;

    if (opA.type === 'insert' && opB.type === 'insert') {
      const insertKindDifference =
        getInsertKindPriorityForSamePath(opA.insertKind) -
        getInsertKindPriorityForSamePath(opB.insertKind);
      if (insertKindDifference !== 0) return insertKindDifference;

      // Apply the last change first so that, at the same insertion point,
      // the events end up in the order of the changes.
      return (opB.order || 0) - (opA.order || 0);
    }

    return 0;
  });

  let applied = 0;
  deduplicatedOperations.forEach(op => {
    const pathForLog = op.path.join('.');
    try {
      if (op.type === 'delete') {
        const { parentList, eventIndexInParentList } = getParentListAndIndex(
          sceneEvents,
          op.path,
          'access' // Deleting an existing event, so 'access'
        );
        // Check already done by getParentListAndIndex for 'access'
        parentList.removeEventAt(eventIndexInParentList);
        applied++;
      } else if (op.type === 'insert') {
        const {
          parentList,
          eventIndexInParentList: insertionIndex,
        } = getParentListAndIndex(
          sceneEvents,
          op.path,
          'insertion' // Path is for insertion point
        );
        // Check already done by getParentListAndIndex for 'insertion'
        if (op.eventsToInsert && !op.eventsToInsert.isEmpty()) {
          parentList.insertEvents(
            // $FlowFixMe[incompatible-type]
            op.eventsToInsert,
            0,
            // $FlowFixMe[incompatible-use]
            op.eventsToInsert.getEventsCount(),
            insertionIndex
          );
          applied++;
        } else {
          errors.push(
            `Insert operation for path [${pathForLog}] skipped: no events to insert or events list is empty.`
          );
        }
      } else if (op.type === 'insertAsSub') {
        // op.path is the path to the PARENT event
        const parentEvent = getEventByPath(sceneEvents, op.path);
        if (!parentEvent.canHaveSubEvents()) {
          errors.push(
            `Cannot insert sub-events: Event at path [${pathForLog}] does not support sub-events. Skipping.`
          );
          return;
        }
        const subEventsList = parentEvent.getSubEvents();
        if (op.eventsToInsert && !op.eventsToInsert.isEmpty()) {
          subEventsList.insertEvents(
            // $FlowFixMe[incompatible-type]
            op.eventsToInsert,
            0,
            // $FlowFixMe[incompatible-use]
            op.eventsToInsert.getEventsCount(),
            subEventsList.getEventsCount() // Insert at the end of sub-events
          );
          applied++;
        } else {
          errors.push(
            `InsertAsSub operation for parent path [${pathForLog}] skipped: no events to insert or events list is empty.`
          );
        }
      } else if (op.type === 'replaceKeepSubEvents') {
        // Replace the event but keep existing sub-events
        const { parentList, eventIndexInParentList } = getParentListAndIndex(
          sceneEvents,
          op.path,
          'access'
        );
        const targetEvent = parentList.getEventAt(eventIndexInParentList);

        // Get existing sub-events from target event before replacement
        let existingSubEvents: gdEventsList | null = null;
        if (targetEvent.canHaveSubEvents()) {
          existingSubEvents = new gd.EventsList();
          const targetSubEvents = targetEvent.getSubEvents();
          existingSubEvents.insertEvents(
            targetSubEvents,
            0,
            targetSubEvents.getEventsCount(),
            0
          );
        }

        // Delete the target event
        parentList.removeEventAt(eventIndexInParentList);

        // Insert new events from generated events
        if (op.eventsToInsert && !op.eventsToInsert.isEmpty()) {
          parentList.insertEvents(
            // $FlowFixMe[incompatible-type]
            op.eventsToInsert,
            0,
            // $FlowFixMe[incompatible-use]
            op.eventsToInsert.getEventsCount(),
            eventIndexInParentList
          );

          // If there were existing sub-events, add them to the first new event
          if (existingSubEvents && existingSubEvents.getEventsCount() > 0) {
            const firstNewEvent = parentList.getEventAt(eventIndexInParentList);
            if (firstNewEvent.canHaveSubEvents()) {
              const newSubEvents = firstNewEvent.getSubEvents();
              // Insert existing sub-events at the beginning
              newSubEvents.insertEvents(
                existingSubEvents,
                0,
                existingSubEvents.getEventsCount(),
                0
              );
            }
          }
        }

        if (existingSubEvents) {
          existingSubEvents.delete();
        }
        applied++;
      } else if (op.type === 'insertActionsConditionsAtEnd') {
        // Copy actions/conditions from generated event(s) to target event at end
        const targetEvent = getEventByPath(sceneEvents, op.path);
        const eventsToInsert = op.eventsToInsert;
        if (eventsToInsert && !eventsToInsert.isEmpty()) {
          for (let i = 0; i < eventsToInsert.getEventsCount(); i++) {
            const sourceEvent = eventsToInsert.getEventAt(i);

            // Copy conditions
            const sourceConditions = getEventConditions(sourceEvent);
            const targetConditions = getEventConditions(targetEvent);
            if (sourceConditions && targetConditions) {
              copyInstructions(
                sourceConditions,
                targetConditions,
                targetConditions.size()
              );
            }

            // Copy actions
            const sourceActions = getEventActions(sourceEvent);
            const targetActions = getEventActions(targetEvent);
            if (sourceActions && targetActions) {
              copyInstructions(
                sourceActions,
                targetActions,
                targetActions.size()
              );
            }

            // Copy while conditions if both are While events
            const sourceWhileConditions = getEventWhileConditions(sourceEvent);
            const targetWhileConditions = getEventWhileConditions(targetEvent);
            if (sourceWhileConditions && targetWhileConditions) {
              copyInstructions(
                sourceWhileConditions,
                targetWhileConditions,
                targetWhileConditions.size()
              );
            }
          }
        }
        applied++;
      } else if (op.type === 'insertActionsConditionsAtStart') {
        // Copy actions/conditions from generated event(s) to target event at start
        const targetEvent = getEventByPath(sceneEvents, op.path);
        const eventsToInsert = op.eventsToInsert;
        if (eventsToInsert && !eventsToInsert.isEmpty()) {
          // Process in reverse order so that insertion at start maintains order
          for (let i = eventsToInsert.getEventsCount() - 1; i >= 0; i--) {
            const sourceEvent = eventsToInsert.getEventAt(i);

            // Copy conditions at start
            const sourceConditions = getEventConditions(sourceEvent);
            const targetConditions = getEventConditions(targetEvent);
            if (sourceConditions && targetConditions) {
              copyInstructions(sourceConditions, targetConditions, 0);
            }

            // Copy actions at start
            const sourceActions = getEventActions(sourceEvent);
            const targetActions = getEventActions(targetEvent);
            if (sourceActions && targetActions) {
              copyInstructions(sourceActions, targetActions, 0);
            }

            // Copy while conditions at start if both are While events
            const sourceWhileConditions = getEventWhileConditions(sourceEvent);
            const targetWhileConditions = getEventWhileConditions(targetEvent);
            if (sourceWhileConditions && targetWhileConditions) {
              copyInstructions(sourceWhileConditions, targetWhileConditions, 0);
            }
          }
        }
        applied++;
      } else if (op.type === 'replaceAllActions') {
        // Clear target event actions and replace with generated event(s) actions
        const targetEvent = getEventByPath(sceneEvents, op.path);
        const targetActions = getEventActions(targetEvent);
        if (targetActions) {
          targetActions.clear();
          const eventsToInsert = op.eventsToInsert;
          if (eventsToInsert && !eventsToInsert.isEmpty()) {
            for (let i = 0; i < eventsToInsert.getEventsCount(); i++) {
              const sourceEvent = eventsToInsert.getEventAt(i);
              const sourceActions = getEventActions(sourceEvent);
              if (sourceActions) {
                copyInstructions(
                  sourceActions,
                  targetActions,
                  targetActions.size()
                );
              }
            }
          }
        }
        applied++;
      } else if (op.type === 'replaceAllConditions') {
        // Clear target event conditions and replace with generated event(s) conditions
        const targetEvent = getEventByPath(sceneEvents, op.path);
        const eventsToInsert = op.eventsToInsert;
        const targetConditions = getEventConditions(targetEvent);
        if (targetConditions) {
          targetConditions.clear();
          if (eventsToInsert && !eventsToInsert.isEmpty()) {
            for (let i = 0; i < eventsToInsert.getEventsCount(); i++) {
              const sourceEvent = eventsToInsert.getEventAt(i);
              const sourceConditions = getEventConditions(sourceEvent);
              if (sourceConditions) {
                copyInstructions(
                  sourceConditions,
                  targetConditions,
                  targetConditions.size()
                );
              }
            }
          }
        }

        // Also replace while conditions if both are While events
        const targetWhileConditions = getEventWhileConditions(targetEvent);
        if (targetWhileConditions) {
          targetWhileConditions.clear();
          if (eventsToInsert && !eventsToInsert.isEmpty()) {
            for (let i = 0; i < eventsToInsert.getEventsCount(); i++) {
              const sourceEvent = eventsToInsert.getEventAt(i);
              const sourceWhileConditions = getEventWhileConditions(
                sourceEvent
              );
              if (sourceWhileConditions) {
                copyInstructions(
                  sourceWhileConditions,
                  targetWhileConditions,
                  targetWhileConditions.size()
                );
              }
            }
          }
        }
        applied++;
      }
    } catch (error) {
      errors.push(
        `Error applying event operation type ${
          op.type
        } for path [${pathForLog}]: ${error.message}`
      );
    } finally {
      // Clean up the gd.EventsList associated with this operation, if any.
      if (op.eventsToInsert) {
        op.eventsToInsert.delete();
      }
    }
  });

  return { applied, errors };
};

/**
 * The variables container an undeclared variable must be declared in: the
 * project or the scene for a scene, the two containers of the extension for
 * a function of an extension (there is no scene nor project variable
 * reachable from a function). Null when the scope has no such container, or
 * when the required scope is not one the generator can ask for.
 */
const getUndeclaredVariableContainer = (
  project: gdProject,
  resolvedScope: ResolvedScope,
  requiredScope: string
): gdVariablesContainer | null => {
  const isGlobal = requiredScope === 'global';
  const isScene = requiredScope === 'scene' || requiredScope === 'none';
  if (!isGlobal && !isScene) return null;

  const { layout, eventsFunctionsExtension } = resolvedScope;
  if (layout) {
    return isGlobal ? project.getVariables() : layout.getVariables();
  }
  if (eventsFunctionsExtension) {
    // Inside a function, the extension variables are the only ones that can
    // be declared. The generator is not supposed to ask for any (it emits a
    // diagnostic naming the parameters, properties and extension variables
    // instead), but a variable must never end up in a wrong container.
    return isGlobal
      ? eventsFunctionsExtension.getGlobalVariables()
      : eventsFunctionsExtension.getSceneVariables();
  }
  return null;
};

const castVariableToType = (variable: gdVariable, type: string) => {
  const lowerCaseType = type.toLowerCase();
  variable.castTo(
    lowerCaseType === 'string'
      ? 'string'
      : lowerCaseType === 'boolean'
      ? 'boolean'
      : lowerCaseType === 'array'
      ? 'array'
      : lowerCaseType === 'structure'
      ? 'structure'
      : 'number'
  );
};

export const addUndeclaredVariables = ({
  project,
  resolvedScope,
  undeclaredVariables,
}: {|
  project: gdProject,
  resolvedScope: ResolvedScope,
  undeclaredVariables: Array<AiGeneratedEventUndeclaredVariable>,
|}) => {
  undeclaredVariables.forEach(variable => {
    const { name, type, requiredScope } = variable;
    const variablesContainer = getUndeclaredVariableContainer(
      project,
      resolvedScope,
      requiredScope
    );
    if (!variablesContainer) {
      console.warn(
        `Unknown requiredScope for undeclared variable: ${name}. Skipping.`
      );
      return;
    }

    if (variablesContainer.has(name)) return;
    const newVariable = variablesContainer.insertNew(name, 0);
    if (type) castVariableToType(newVariable, type);
  });
};

/**
 * The child objects a name designates inside a function of an extension: a
 * child object of the custom object owning the function, or every child of a
 * group of them. Empty for `Object` and for the object parameters of the
 * function: they are picked at runtime and own no variable nor behavior (the
 * generator is told to use a `behavior` parameter or a property instead).
 */
const getChildObjectsInScope = (
  resolvedScope: ResolvedScope,
  objectName: string
): Array<gdObject> => {
  const { eventsBasedObject } = resolvedScope;
  if (!eventsBasedObject) return [];
  // The children of the default variant hold the structure of the custom
  // object: the named variants are complied to them afterwards.
  const childObjects = eventsBasedObject.getObjects();
  if (childObjects.hasObjectNamed(objectName)) {
    return [childObjects.getObject(objectName)];
  }
  const objectGroups = childObjects.getObjectGroups();
  if (objectGroups.has(objectName)) {
    return objectGroups
      .get(objectName)
      .getAllObjectsNames()
      .toJSArray()
      .filter(childName => childObjects.hasObjectNamed(childName))
      .map(childName => childObjects.getObject(childName));
  }
  return [];
};

const setupVariable = (variable: gdVariable, type: string | null) => {
  if (!type) {
    return;
  }
  castVariableToType(variable, type);
};

/**
 * Declare the object variables of a generated event inside a function of an
 * extension: only a child object of the custom object owning the function can
 * receive them.
 */
const addChildObjectUndeclaredVariables = ({
  resolvedScope,
  objectName,
  undeclaredVariables,
}: {|
  resolvedScope: ResolvedScope,
  objectName: string,
  undeclaredVariables: Array<AiGeneratedEventUndeclaredVariable>,
|}) => {
  const childObjects = getChildObjectsInScope(resolvedScope, objectName);
  if (childObjects.length === 0) {
    console.warn(
      `Object "${objectName}" is not a child object of ${
        resolvedScope.label
      }: its variable(s) cannot be declared there. Skipping.`
    );
    return;
  }

  undeclaredVariables.forEach(undeclaredVariable => {
    childObjects.forEach(childObject => {
      const variablesContainer = childObject.getVariables();
      if (variablesContainer.has(undeclaredVariable.name)) return;
      setupVariable(
        variablesContainer.insertNew(undeclaredVariable.name, 0),
        undeclaredVariable.type
      );
    });
  });
};

export const addObjectUndeclaredVariables = ({
  project,
  resolvedScope,
  objectName,
  undeclaredVariables,
}: {|
  project: gdProject,
  resolvedScope: ResolvedScope,
  objectName: string,
  undeclaredVariables: Array<AiGeneratedEventUndeclaredVariable>,
|}) => {
  const scene = resolvedScope.layout;
  if (!scene) {
    addChildObjectUndeclaredVariables({
      resolvedScope,
      objectName,
      undeclaredVariables,
    });
    return;
  }

  const projectScopedContainers = gd.ProjectScopedContainers.makeNewProjectScopedContainersForProjectAndLayout(
    project,
    scene
  );

  const addVariableForObjectsOfGroup = (
    group: gdObjectGroup,
    undeclaredVariable: AiGeneratedEventUndeclaredVariable
  ) => {
    const groupVariablesContainer = gd.ObjectRefactorer.mergeVariableContainers(
      projectScopedContainers.getObjectsContainersList(),
      group
    );
    const originalSerializedVariables = new gd.SerializerElement();
    groupVariablesContainer.serializeTo(originalSerializedVariables);

    const variable = groupVariablesContainer.insertNew(
      undeclaredVariable.name,
      0
    );
    setupVariable(variable, undeclaredVariable.type);

    const changeset = gd.WholeProjectRefactorer.computeChangesetForVariablesContainer(
      originalSerializedVariables,
      groupVariablesContainer
    );

    gd.WholeProjectRefactorer.applyRefactoringForGroupVariablesContainer(
      project,
      project.getObjects(),
      scene.getObjects(),
      scene.getInitialInstances(),
      groupVariablesContainer,
      group,
      changeset,
      originalSerializedVariables
    );
    originalSerializedVariables.delete();
  };

  undeclaredVariables.forEach(undeclaredVariable => {
    if (
      projectScopedContainers
        .getObjectsContainersList()
        .hasObjectOrGroupWithVariableNamed(objectName, undeclaredVariable.name)
    ) {
      // Variable already exists, no need to add it.
      return;
    }

    if (scene.getObjects().hasObjectNamed(objectName)) {
      const object = scene.getObjects().getObject(objectName);
      const variable = object
        .getVariables()
        .insertNew(undeclaredVariable.name, 0);
      setupVariable(variable, undeclaredVariable.type);
    } else if (
      scene
        .getObjects()
        .getObjectGroups()
        .has(objectName)
    ) {
      const group = scene
        .getObjects()
        .getObjectGroups()
        .get(objectName);

      addVariableForObjectsOfGroup(group, undeclaredVariable);
    } else if (project.getObjects().hasObjectNamed(objectName)) {
      const object = project.getObjects().getObject(objectName);
      const variable = object
        .getVariables()
        .insertNew(undeclaredVariable.name, 0);
      setupVariable(variable, undeclaredVariable.type);
    } else if (
      project
        .getObjects()
        .getObjectGroups()
        .has(objectName)
    ) {
      const group = project
        .getObjects()
        .getObjectGroups()
        .get(objectName);

      addVariableForObjectsOfGroup(group, undeclaredVariable);
    }
  });
};

/**
 * Whether a missing behavior can be added at all: an unknown type or a
 * default capability (always there, not addable) is skipped with a warning.
 */
const canAddMissingBehavior = (
  project: gdProject,
  missingBehavior: AiGeneratedEventMissingObjectBehavior,
  objectName: string
): boolean => {
  const behaviorMetadata = gd.MetadataProvider.getBehaviorMetadata(
    project.getCurrentPlatform(),
    missingBehavior.type
  );

  if (gd.MetadataProvider.isBadBehaviorMetadata(behaviorMetadata)) {
    console.warn(`Unknown behavior type: "${missingBehavior.type}". Skipping.`);
    return false;
  }

  if (isBehaviorDefaultCapability(behaviorMetadata)) {
    console.warn(
      `Behavior "${missingBehavior.name}" of type "${
        missingBehavior.type
      }" is a default capability and cannot be added to object "${objectName}".`
    );
    return false;
  }

  return true;
};

const addBehaviorToObject = (
  project: gdProject,
  object: gdObject,
  behaviorName: string,
  behaviorType: string
) => {
  if (object.hasBehaviorNamed(behaviorName)) {
    return;
  }

  gd.WholeProjectRefactorer.addBehaviorAndRequiredBehaviors(
    project,
    object,
    behaviorType,
    behaviorName
  );
};

/**
 * Add the behaviors a generated event needs to a child object of the custom
 * object owning the function. `Object` and the object parameters never get
 * one: a parameter cannot receive a behavior (the fix is a `behavior`
 * parameter or a `Behavior` property of the object/behavior).
 */
const addMissingChildObjectBehaviors = ({
  project,
  resolvedScope,
  objectName,
  missingBehaviors,
}: {|
  project: gdProject,
  resolvedScope: ResolvedScope,
  objectName: string,
  missingBehaviors: Array<AiGeneratedEventMissingObjectBehavior>,
|}) => {
  const childObjects = getChildObjectsInScope(resolvedScope, objectName);
  if (childObjects.length === 0) {
    console.warn(
      `Object "${objectName}" is not a child object of ${
        resolvedScope.label
      }: behavior(s) cannot be added to it (a parameter or "Object" cannot have a behavior added). Skipping.`
    );
    return;
  }

  missingBehaviors.forEach(missingBehavior => {
    if (!canAddMissingBehavior(project, missingBehavior, objectName)) return;

    childObjects.forEach(childObject => {
      addBehaviorToObject(
        project,
        childObject,
        missingBehavior.name,
        missingBehavior.type
      );
    });
  });
  // A child object can be used in any scene: refresh the shared data of the
  // whole project (there is no scene to refresh here).
  updateBehaviorsSharedDataInScope(project, resolvedScope);
};

export const addMissingObjectBehaviors = ({
  project,
  resolvedScope,
  objectName,
  missingBehaviors,
}: {|
  project: gdProject,
  resolvedScope: ResolvedScope,
  objectName: string,
  missingBehaviors: Array<AiGeneratedEventMissingObjectBehavior>,
|}) => {
  const scene = resolvedScope.layout;
  if (!scene) {
    addMissingChildObjectBehaviors({
      project,
      resolvedScope,
      objectName,
      missingBehaviors,
    });
    return;
  }

  const projectScopedContainers = gd.ProjectScopedContainers.makeNewProjectScopedContainersForProjectAndLayout(
    project,
    scene
  );

  const objectOrGroupBehaviorNames = projectScopedContainers
    .getObjectsContainersList()
    .getBehaviorsOfObject(objectName, true)
    .toJSArray();

  const addBehaviorToObjectGroup = (
    group: gdObjectGroup,
    behaviorName: string,
    behaviorType: string
  ) => {
    const objectNames = group.getAllObjectsNames().toJSArray();
    objectNames.forEach(objectName => {
      if (scene.getObjects().hasObjectNamed(objectName)) {
        const object = scene.getObjects().getObject(objectName);
        addBehaviorToObject(project, object, behaviorName, behaviorType);
      } else if (project.getObjects().hasObjectNamed(objectName)) {
        const object = project.getObjects().getObject(objectName);
        addBehaviorToObject(project, object, behaviorName, behaviorType);
      }
    });
  };

  missingBehaviors.forEach(missingBehavior => {
    if (objectOrGroupBehaviorNames.includes(missingBehavior.name)) {
      // This behavior is already present, no need to add it.
      return;
    }

    if (!canAddMissingBehavior(project, missingBehavior, objectName)) return;

    if (scene.getObjects().hasObjectNamed(objectName)) {
      const object = scene.getObjects().getObject(objectName);
      addBehaviorToObject(
        project,
        object,
        missingBehavior.name,
        missingBehavior.type
      );
    } else if (
      scene
        .getObjects()
        .getObjectGroups()
        .has(objectName)
    ) {
      const group = scene
        .getObjects()
        .getObjectGroups()
        .get(objectName);

      addBehaviorToObjectGroup(
        group,
        missingBehavior.name,
        missingBehavior.type
      );
    } else if (project.getObjects().hasObjectNamed(objectName)) {
      const object = project.getObjects().getObject(objectName);
      addBehaviorToObject(
        project,
        object,
        missingBehavior.name,
        missingBehavior.type
      );
    } else if (
      project
        .getObjects()
        .getObjectGroups()
        .has(objectName)
    ) {
      const group = project
        .getObjects()
        .getObjectGroups()
        .get(objectName);

      addBehaviorToObjectGroup(
        group,
        missingBehavior.name,
        missingBehavior.type
      );
    }
  });

  scene.updateBehaviorsSharedData(project);
};
